-- Desktop shortcuts. Locked/repeating/mouse flags match the original bindings.
-- Every binding carries a description so Luma's shortcut search (Super+/) lists it.
hl.bind("SUPER + X", hl.dsp.exec_cmd("~/.dotfiles/scripts/launch_kitty.sh"), { description = "Open a terminal" })
hl.bind("SUPER + Q", hl.dsp.exec_cmd("~/.dotfiles/scripts/launch_kitty.sh"), { description = "Open a terminal" })
hl.bind("SUPER + B", hl.dsp.exec_cmd("vigil control-center toggle"), { description = "Toggle quick settings" })
hl.bind("SUPER + T", hl.dsp.exec_cmd("tv-mode start"), { description = "Start TV mode" })
hl.bind("SUPER + W", hl.dsp.window.close(), { description = "Close window" })
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("Luma --toggle"), { description = "Search apps files and actions" })
hl.bind("SUPER + TAB", hl.dsp.exec_cmd("Luma --mode windows --toggle"), { description = "Search open windows" })
hl.bind("SUPER + SHIFT + SPACE", hl.dsp.exec_cmd("Luma --mode controls --toggle"), { description = "Search desktop controls" })
hl.bind("SUPER + slash", hl.dsp.exec_cmd("Luma --mode keys --toggle"), { description = "Search keyboard shortcuts" })
hl.bind("SUPER + SHIFT + V", hl.dsp.exec_cmd("Luma --mode clipboard --toggle"), { description = "Search clipboard history" })
hl.bind("SUPER + CTRL + SPACE", hl.dsp.exec_cmd("hyprctl switchxkblayout all next"), { description = "Switch keyboard layout" })
hl.bind("SUPER + SHIFT + N", hl.dsp.exec_cmd("vigil control-center toggle --context notifications"), { description = "Toggle notification inbox" })
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "maximized" }), { description = "Toggle maximized window" })
hl.bind("SUPER + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }), { description = "Toggle fullscreen" })
hl.bind("SUPER + V", hl.dsp.window.float({ action = "toggle" }), { description = "Toggle floating window" })
hl.bind("SUPER + SHIFT + F1", hl.dsp.window.fullscreen({ mode = "fullscreen" }), { description = "Toggle fullscreen" })
hl.bind("SUPER + SHIFT + F4", hl.dsp.window.fullscreen({ mode = "maximized" }), { description = "Toggle maximized window" })
hl.bind("SUPER + SHIFT + F3", hl.dsp.window.float({ action = "toggle" }), { description = "Toggle floating window" })
hl.bind("SUPER + SHIFT + F2", hl.dsp.window.pseudo(), { description = "Toggle pseudo-tiling" })
hl.bind("SUPER + CTRL + F1", hl.dsp.window.pin(), { description = "Pin window to all workspaces" })
hl.bind("SUPER + J", hl.dsp.layout("togglesplit"), { description = "Toggle split direction" })
hl.bind("SUPER + P", hl.dsp.exec_cmd("Luma --mode pass --toggle"), { description = "Search passwords" })
hl.bind("SUPER + Return", hl.dsp.exec_cmd("kitten quick-access-terminal"), { description = "Toggle drop-down terminal" })
hl.bind("Print", hl.dsp.exec_cmd("~/.dotfiles/scripts/screenshot.sh area"), { description = "Screenshot an area" })
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("~/.dotfiles/scripts/screenshot.sh output"), { description = "Screenshot the focused monitor" })
hl.bind("SUPER + Print", hl.dsp.exec_cmd("~/.dotfiles/scripts/screenshot.sh area"), { description = "Screenshot an area" })
hl.bind("SUPER + left", hl.dsp.focus({ direction = "left" }), { description = "Focus window left" })
hl.bind("SUPER + right", hl.dsp.focus({ direction = "right" }), { description = "Focus window right" })
hl.bind("SUPER + up", hl.dsp.focus({ direction = "up" }), { description = "Focus window up" })
hl.bind("SUPER + down", hl.dsp.focus({ direction = "down" }), { description = "Focus window down" })
hl.bind("SUPER + SHIFT + left", hl.dsp.window.move({ direction = "left" }), { description = "Move window left" })
hl.bind("SUPER + SHIFT + right", hl.dsp.window.move({ direction = "right" }), { description = "Move window right" })
hl.bind("SUPER + SHIFT + up", hl.dsp.window.move({ direction = "up" }), { description = "Move window up" })
hl.bind("SUPER + SHIFT + down", hl.dsp.window.move({ direction = "down" }), { description = "Move window down" })
hl.bind("SUPER + CTRL + left", hl.dsp.window.resize({ x = -40, y = 0, relative = true }), { repeating = true, description = "Shrink window width" })
hl.bind("SUPER + CTRL + right", hl.dsp.window.resize({ x = 40, y = 0, relative = true }), { repeating = true, description = "Grow window width" })
hl.bind("SUPER + CTRL + up", hl.dsp.window.resize({ x = 0, y = -40, relative = true }), { repeating = true, description = "Shrink window height" })
hl.bind("SUPER + CTRL + down", hl.dsp.window.resize({ x = 0, y = 40, relative = true }), { repeating = true, description = "Grow window height" })
hl.bind("SUPER + grave", hl.dsp.focus({ workspace = "previous" }), { description = "Return to previous workspace" })
hl.bind("SUPER + 1", hl.dsp.focus({ workspace = "1" }), { description = "Go to workspace 1" })
hl.bind("SUPER + 2", hl.dsp.focus({ workspace = "2" }), { description = "Go to workspace 2" })
hl.bind("SUPER + 3", hl.dsp.focus({ workspace = "3" }), { description = "Go to workspace 3" })
hl.bind("SUPER + 4", hl.dsp.focus({ workspace = "4" }), { description = "Go to workspace 4" })
hl.bind("SUPER + 5", hl.dsp.focus({ workspace = "5" }), { description = "Go to workspace 5" })
hl.bind("SUPER + 6", hl.dsp.focus({ workspace = "6" }), { description = "Go to workspace 6" })
hl.bind("SUPER + 7", hl.dsp.focus({ workspace = "7" }), { description = "Go to workspace 7" })
hl.bind("SUPER + 8", hl.dsp.focus({ workspace = "8" }), { description = "Go to workspace 8" })
hl.bind("SUPER + 9", hl.dsp.focus({ workspace = "9" }), { description = "Go to workspace 9" })
hl.bind("SUPER + 0", hl.dsp.focus({ workspace = "10" }), { description = "Go to workspace 10" })
hl.bind("SUPER + SHIFT + 1", hl.dsp.window.move({ workspace = "1" }), { description = "Move window to workspace 1" })
hl.bind("SUPER + SHIFT + 2", hl.dsp.window.move({ workspace = "2" }), { description = "Move window to workspace 2" })
hl.bind("SUPER + SHIFT + 3", hl.dsp.window.move({ workspace = "3" }), { description = "Move window to workspace 3" })
hl.bind("SUPER + SHIFT + 4", hl.dsp.window.move({ workspace = "4" }), { description = "Move window to workspace 4" })
hl.bind("SUPER + SHIFT + 5", hl.dsp.window.move({ workspace = "5" }), { description = "Move window to workspace 5" })
hl.bind("SUPER + SHIFT + 6", hl.dsp.window.move({ workspace = "6" }), { description = "Move window to workspace 6" })
hl.bind("SUPER + SHIFT + 7", hl.dsp.window.move({ workspace = "7" }), { description = "Move window to workspace 7" })
hl.bind("SUPER + SHIFT + 8", hl.dsp.window.move({ workspace = "8" }), { description = "Move window to workspace 8" })
hl.bind("SUPER + SHIFT + 9", hl.dsp.window.move({ workspace = "9" }), { description = "Move window to workspace 9" })
hl.bind("SUPER + SHIFT + 0", hl.dsp.window.move({ workspace = "10" }), { description = "Move window to workspace 10" })
hl.bind("SUPER + mouse_down", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind("SUPER + mouse_up", hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true, description = "Drag window" })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Resize window" })
hl.bind("SUPER + A", hl.dsp.layout("preselect l"), { description = "Open next window to the left" })
hl.bind("SUPER + L", hl.dsp.exec_cmd("~/.dotfiles/scripts/session_lock.sh"), { locked = true, description = "Lock the screen" })
-- Vigil shows the resulting level; `&&` keeps a failed change from showing a stale one.
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 0.05+ -l 1.0 && vigil osd volume"), { locked = true, repeating = true, description = "Raise volume" })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 0.05- && vigil osd volume"), { locked = true, repeating = true, description = "Lower volume" })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle && vigil osd volume"), { locked = true, description = "Mute audio" })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle && vigil osd microphone"), { locked = true, description = "Mute microphone" })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("~/.dotfiles/scripts/now_playing.sh --toggle"), { locked = true, description = "Play or pause media" })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("~/.dotfiles/scripts/now_playing.sh --toggle"), { locked = true, description = "Play or pause media" })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("~/.dotfiles/scripts/now_playing.sh --previous"), { locked = true, description = "Previous track" })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("~/.dotfiles/scripts/now_playing.sh --next"), { locked = true, description = "Next track" })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl --class=backlight set +5% && vigil osd brightness"), { locked = true, repeating = true, description = "Raise brightness" })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl --class=backlight set 5%- && vigil osd brightness"), { locked = true, repeating = true, description = "Lower brightness" })
